/* Public API: bridge entrypoints for embedding in a shim device. */
uint64_t kmac_read(void *opaque, hwaddr addr, unsigned size);
void     kmac_write(void *opaque, hwaddr addr,
            uint64_t value, unsigned size);
/* Asserts rst_ni for one settle round, then releases — primes the
 * model so registers with non-zero RESVALs see their reset value. */
void kmac_reset(kmac_state *s);
/* Run the model to quiescence without a bus access (external event
 * sources — SPI pumps, pin changes — call this after poking inputs). */
void kmac_settle(kmac_state *s);

void kmac_step(kmac_state *s);
void kmac_update(kmac_state *s);
void kmac_tick(kmac_state *s);

void kmac_step_many(kmac_state *s, unsigned count);

/* Phase 2.d input setters — bridge host-side QEMU events into
 * the simulated device.  Each writes one input-port leaf field
 * and runs update_state→tick→update_state to settle.
 */
void kmac_set_rst_shadowed_ni(kmac_state *s, uint8_t value);
void kmac_set_clk_edn_i(kmac_state *s, uint8_t value);
void kmac_set_rst_edn_ni(kmac_state *s, uint8_t value);
void kmac_set_alert_rx_i_0__ping_p(kmac_state *s, uint8_t value);
void kmac_set_alert_rx_i_0__ping_n(kmac_state *s, uint8_t value);
void kmac_set_alert_rx_i_0__ack_p(kmac_state *s, uint8_t value);
void kmac_set_alert_rx_i_0__ack_n(kmac_state *s, uint8_t value);
void kmac_set_alert_rx_i_1__ping_p(kmac_state *s, uint8_t value);
void kmac_set_alert_rx_i_1__ping_n(kmac_state *s, uint8_t value);
void kmac_set_alert_rx_i_1__ack_p(kmac_state *s, uint8_t value);
void kmac_set_alert_rx_i_1__ack_n(kmac_state *s, uint8_t value);
void kmac_set_keymgr_key_i_valid(kmac_state *s, uint8_t value);
void kmac_set_keymgr_key_i_key_0_(kmac_state *s, const uint64_t value[4]);
void kmac_set_keymgr_key_i_key_1_(kmac_state *s, const uint64_t value[4]);
void kmac_set_entropy_i_edn_ack(kmac_state *s, uint8_t value);
void kmac_set_entropy_i_edn_fips(kmac_state *s, uint8_t value);
void kmac_set_entropy_i_edn_bus(kmac_state *s, uint32_t value);
void kmac_set_lc_escalate_en_i(kmac_state *s, uint8_t value);

#endif /* KMAC_H */
